/**
 * dsh-baizhu-approval — client half(浏览器 bundle)
 *
 * 以 composer chain 接管的方式替换内置审批面板,把两个源码补丁迁移成插件:
 *
 *   approval-always-allow.patch:
 *     - 第三个按钮「总是允许」:选择后本次页面运行内、该会话的所有审批
 *       自动放行(相当于原补丁进程内存中的 confirm-writes/always-allow
 *       广播,但完全在客户端实现,不改 API wire schema)
 *   approval-keyboard.patch:
 *     - Esc = 拒绝,Ctrl/Cmd+Enter = 允许一次,
 *       Ctrl/Cmd+Shift+Enter = 总是允许(按钮 title 同步提示)
 *
 * 加载协议:本文件是 classic script,由 client-modules 以
 * <script src="/plugins/dsh-baizhu-approval/client.js"> 拉取;
 * 脚本只向 window.__ModuleLoader__ 注册 factory,模块体(含 CSS 注入)
 * 都在 factory 内部,与 dsh 的 lazy CJS 模型一致。
 * factory 内的同步 require 只使用平台种子词(react、ui-primitives)。
 */

;(function registerClientBundle() {
  if (typeof window === 'undefined' || typeof window.__ModuleLoader__ === 'undefined') return
  window.__ModuleLoader__.load({
    id: 'dsh-baizhu-approval',
    factory: function approvalTweaksFactory(require) {
      'use strict'
      const React = require('react')
      const { Button } = require('@deepseek-ai/dsh-client-ui-primitives')

      // ── CSS 注入(factory 内副作用,模块系统会登记为插件样式)──────────
      const cssText = `
/* 与内置 ApprovalPanel.module.css 相同的外观:浮层胶囊卡片 + 琥珀色警示带 */
.dba-root {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px calc(var(--dsh-composer-side-clearance) + 16px) 12px;
}
.dba-card {
  overflow: hidden;
  width: 100%;
  max-width: var(--dsh-chat-content-width);
  border: 1px solid var(--dsw-alias-state-warn-secondary);
  border-radius: 20px;
  background: var(--dsw-specific-input-major);
  box-shadow: var(--dsw-shadow-lv2);
  --dsh-scrollbar-thumb: var(--dsw-alias-scrollbar-bg-l2);
  --dsh-scrollbar-thumb-hover: var(--dsw-alias-scrollbar-hover-l2);
}
.dba-strip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--dsw-alias-state-warn-tertiary);
  color: var(--dsw-alias-state-warn-primary);
  font-size: 13px;
  line-height: 18px;
}
.dba-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--dsw-alias-state-warn-primary);
}
.dba-body {
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-sizing: border-box;
  max-height: var(--dsh-composer-text-max-height);
  overflow-y: auto;
  padding: 12px 16px 0;
}
.dba-headline {
  color: var(--dsw-alias-label-primary);
  font-size: 15px;
  font-weight: 500;
  line-height: 24px;
}
.dba-command {
  color: var(--dsw-alias-label-tertiary);
  font-family: var(--ds-font-family-code);
  font-size: 13px;
  line-height: 20px;
  word-break: break-all;
}
.dba-actionRow {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 14px 16px 14px;
}
.dba-reject:hover:not(:disabled) {
  background: var(--dsw-alias-interactive-bg-hover-danger);
  color: var(--dsw-alias-state-error-primary);
  border-color: transparent;
}
/* 总是允许:拒绝方向的副按钮,悬停保持中性即可 */
.dba-alwaysAllow:hover:not(:disabled) {
  background: var(--dsw-alias-interactive-bg-hover-solid);
  color: var(--dsw-alias-label-primary);
}
/* 自动放行时的占位卡片:避免审批面板消失后 composer 区域闪现空白 */
.dba-placeholder {
  min-height: 64px;
}
`
      if (typeof document !== 'undefined') {
        const style = document.createElement('style')
        style.textContent = cssText
        document.head.appendChild(style)
      }

      // ── 文案(与原补丁 locales 一致) ────────────────────────────────
      const NS = 'approval-tweaks'
      const zh = {
        'approval.waiting': '等待审批',
        'approval.detail.aria': '审批详情',
        'approval.escalation': '工具 {toolName} 请求越权执行',
        'approval.reject': '拒绝',
        'approval.allowOnce': '允许一次',
        'approval.alwaysAllow': '总是允许',
      }
      const en = {
        'approval.waiting': 'Waiting for approval',
        'approval.detail.aria': 'Approval details',
        'approval.escalation': 'Tool {toolName} requests privileged execution',
        'approval.reject': 'Reject',
        'approval.allowOnce': 'Allow once',
        'approval.alwaysAllow': 'Always allow',
      }

      // 「总是允许」会话集合:仅存于本页面内存(等价于原补丁的进程内存,
      // 页面刷新/重启后自动恢复询问,不随会话持久化)。
      const alwaysAllowSessions = new Set()

      // 纯函数:chain 选择器必须只依赖 owner props,不能读外部可变状态。
      function selectApproval({ interactions }) {
        for (const interaction of interactions ?? []) {
          if (interaction?.kind === 'approval') return interaction
        }
        return null
      }

      // 与 runtime 的 conversationContextKey('tool-call', id) 等价: `${len}:${kind}${id}`
      function toolContextKey(kind, id) {
        return `${kind.length}:${kind}${id}`
      }

      // 从会话快照提取被询问命令(bash 族参数里的 command;同内置 commandOf)
      function commandOf(snapshot, callId) {
        if (!callId) return undefined
        try {
          const node = snapshot?.chat?.nodes?.get(toolContextKey('tool-call', callId))
          if (node === undefined || node.kind !== 'tool-call') return undefined
          const root = node.data?.root
          if (root === null || root === undefined || 'kind' in root) return undefined
          if (root.callId !== callId) return undefined
          const args = JSON.parse(root.argsRaw)
          return typeof args.command === 'string' ? args.command : undefined
        } catch {
          return undefined
        }
      }

      // 每个请求 key 一个实例,一次性锁存不会泄漏到下一个待审批请求
      function ApprovalPanelOuter(props) {
        const wait = props.matched
        return React.createElement(ApprovalFlow, {
          key: wait.key,
          wait,
          sessionId: props.sessionId,
          useSession: props.useSession,
          t: props.t,
        })
      }

      function ApprovalFlow({ wait, sessionId, useSession, t }) {
        const alwaysAllow = alwaysAllowSessions.has(sessionId)
        const [answered, setAnswered] = React.useState(false)
        const [autoFailed, setAutoFailed] = React.useState(false)
        const autoState = React.useRef('idle') // idle → sent → (failed)

        // 与原 PendingApproval.answer 相同的 wire 编码
        const respond = React.useCallback((outcome) => {
          return wait.respond({
            ok: true,
            value: { sessionId: wait.sessionId, approvalId: wait.payload.approvalId, outcome },
          })
        }, [wait])

        const answer = React.useCallback((outcome) => {
          setAnswered(true)
          void respond(outcome).catch(() => { setAnswered(false) })
        }, [respond])

        const answerAlwaysAllow = React.useCallback(() => {
          alwaysAllowSessions.add(sessionId)
          answer('allowed-once')
        }, [sessionId, answer])

        // 已选「总是允许」的会话:新审批到达后立即放行(布局期应答,
        // 绘制前完成,用户看不到面板);应答失败则回退为可见面板。
        React.useLayoutEffect(() => {
          if (!alwaysAllow || autoState.current !== 'idle') return
          autoState.current = 'sent'
          void respond('allowed-once').catch(() => {
            autoState.current = 'failed'
            setAutoFailed(true)
          })
        }, [alwaysAllow, respond])

        // 命令行:从快照取被询问工具调用参数(同内置面板)
        const command = useSession((snapshot) => commandOf(snapshot, wait.payload.callId))

        const showPanel = !alwaysAllow || autoFailed

        // 键盘快捷键(防误触):Esc=拒绝(拒绝方向安全),
        // Ctrl/Cmd+Enter=允许一次,Ctrl/Cmd+Shift+Enter=总是允许
        React.useEffect(() => {
          if (!showPanel || answered) return
          const onKeyDown = (event) => {
            if (answered) return
            const mod = event.ctrlKey || event.metaKey
            if (event.key === 'Enter' && event.shiftKey && mod) {
              event.preventDefault()
              answerAlwaysAllow()
            } else if (event.key === 'Enter' && mod) {
              event.preventDefault()
              answer('allowed-once')
            } else if (event.key === 'Escape') {
              event.preventDefault()
              answer('rejected')
            }
          }
          document.addEventListener('keydown', onKeyDown)
          return () => document.removeEventListener('keydown', onKeyDown)
        }, [showPanel, answered, answer, answerAlwaysAllow])

        if (!showPanel) {
          // 自动放行中:渲染一个同尺寸占位卡片,避免 composer 闪现空白
          return React.createElement('div', { className: 'dba-root' },
            React.createElement('div', { className: 'dba-card dba-placeholder' }))
        }

        return React.createElement('div', { className: 'dba-root', 'data-approval-key': wait.key },
          React.createElement('div', { className: 'dba-card' },
            React.createElement('div', { className: 'dba-strip' },
              React.createElement('span', { className: 'dba-dot' }),
              t('approval.waiting')),
            React.createElement('div', {
              className: 'dba-body',
              'data-approval-scroll': '',
              tabIndex: 0,
              role: 'group',
              'aria-label': t('approval.detail.aria'),
            },
              React.createElement('div', { className: 'dba-headline' },
                wait.payload.reason ?? t('approval.escalation', { toolName: wait.payload.toolName })),
              command !== undefined
                ? React.createElement('div', { className: 'dba-command' }, command)
                : null),
            React.createElement('div', { className: 'dba-actionRow' },
              React.createElement(Button, {
                variant: 'outline',
                className: 'dba-reject',
                disabled: answered,
                title: `${t('approval.reject')} (Esc)`,
                onClick: () => { answer('rejected') },
              }, t('approval.reject')),
              React.createElement(Button, {
                variant: 'outline',
                className: 'dba-alwaysAllow',
                disabled: answered,
                title: `${t('approval.alwaysAllow')} (Ctrl+Shift+Enter)`,
                onClick: answerAlwaysAllow,
              }, t('approval.alwaysAllow')),
              React.createElement(Button, {
                variant: 'primary',
                disabled: answered,
                title: `${t('approval.allowOnce')} (Ctrl+Enter)`,
                onClick: () => { answer('allowed-once') },
              }, t('approval.allowOnce')))))
      }

      /** 客户端插件导出:等 slots/locale 服务就绪后注册 composer chain 接管。 */
      return {
        name: 'dsh-baizhu-approval',
        inject: ['slots', 'locale'],
        apply(ctx) {
          ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-baizhu-approval: dictionaries')
          ctx.slots.inject('conversation.composer', () => ctx.slots.register({
            name: 'conversation.composer',
            // 内置 approval 面板 priority=1,question 面板默认 0;
            // 0.5 保证「问题优先于审批」的原顺序不变,同时本面板先于内置面板接管审批。
            select: selectApproval,
            priority: 0.5,
            locale: NS,
          }, ApprovalPanelOuter))
        },
      }
    },
  })
})()
